function validateEVSheet() {
  const sh = SpreadsheetApp.getActiveSheet();
  const ui = SpreadsheetApp.getUi();
  const tol = 0.01;

  // Column C is the Value/Formula column
  const ranges = [
    { name: 'Option A', start: 3, end: 10 },  // C3:C10
    { name: 'Option B', start: 18, end: 25 }  // C18:C25
  ];

  // Clear previous backgrounds/notes
  ranges.forEach(r => {
    const range = sh.getRange(r.start, 3, r.end - r.start + 1, 1);
    range.clearNote();
    range.setBackground(null);
  });

  let issues = [];

  ranges.forEach(r => {
    const nRows = r.end - r.start + 1;
    const col = 3; // C
    const vals = sh.getRange(r.start, col, nRows, 1).getValues().map(v => v[0]);

    let probCells = [];
    let payoffCells = [];
    for (let i = 0; i < nRows; i++) {
      const rowNum = r.start + i;
      if (rowNum % 2 === 1) { // odd sheet row -> probability (matches FILTER rule)
        probCells.push({ i, rowNum, val: vals[i] });
      } else {
        payoffCells.push({ i, rowNum, val: vals[i] });
      }
    }

    // Safer pairing logic
    const pairs = [];
    const extraIssues = [];
    const len = Math.min(probCells.length, payoffCells.length);
    for (let k = 0; k < len; k++) {
      pairs.push({ p: probCells[k], x: payoffCells[k] });
    }
    if (payoffCells.length > probCells.length) {
      for (let k = len; k < payoffCells.length; k++) {
        const xr = sh.getRange(payoffCells[k].rowNum, col);
        xr.setBackground('#FFD7AE').setNote('Payoff has no matching probability above.');
        extraIssues.push(`${r.name}: Orphan payoff at C${payoffCells[k].rowNum}.`);
      }
    }
    if (extraIssues.length) issues.push(...extraIssues);

    // Validate each probability and payoff
    let probSum = 0;
    pairs.forEach(({ p, x }) => {
      const pRange = sh.getRange(p.rowNum, col);
      const xRange = sh.getRange(x.rowNum, col);

      const pBlank = p.val === '' || p.val === null;
      const xBlank = x.val === '' || x.val === null;

      // Missing pair check
      if ((pBlank && !xBlank) || (!pBlank && xBlank)) {
        [pRange, xRange].forEach(rr => {
          rr.setBackground('#FFD7AE'); // orange
        });
        issues.push(`${r.name}: Incomplete prob/payoff pair near rows ${p.rowNum}-${x.rowNum}.`);
      }

      // Probability checks
      if (!pBlank) {
        if (typeof p.val !== 'number' || isNaN(p.val)) {
          pRange.setBackground('#F8A8A8').setNote('Probability must be a number in [0,1].');
          issues.push(`${r.name}: Probability at C${p.rowNum} is not a number.`);
        } else if (p.val < 0 || p.val > 1) {
          pRange.setBackground('#F8A8A8').setNote('Probability must be between 0 and 1.');
          issues.push(`${r.name}: Probability at C${p.rowNum} is out of [0,1]..`);
        } else {
          probSum += p.val;
        }
      }

      // Payoff checks
      if (!xBlank) {
        if (typeof x.val !== 'number' || isNaN(x.val)) {
          xRange.setBackground('#F8A8A8').setNote('Payoff must be numeric.');
          issues.push(`${r.name}: Payoff at C${x.rowNum} is not numeric.`);
        }
      }
    });

    // Probability sum check
    if (probSum > 0) { // ignore if all blank
      if (Math.abs(probSum - 1) > tol) {
        probCells.forEach(p => {
          sh.getRange(p.rowNum, col).setBackground('#FFF3B0'); // yellow
        });
        issues.push(`${r.name}: Probabilities sum to ${probSum.toFixed(3)} (expected ~1).`);
      }
    }
  });

  if (issues.length === 0) {
    ui.alert('Validation complete', 'All good: probabilities and payoffs look valid.', ui.ButtonSet.OK);
  } else {
    ui.alert('Validation results', issues.join('\n'), ui.ButtonSet.OK);
  }
}

function insertProbSumHelpers() {
  const ui = SpreadsheetApp.getUi();
  const sh = SpreadsheetApp.getActiveSheet();

  const respA = ui.prompt('Option A helper', 'Enter the cell for the Option A Prob Sum (e.g., E3):', ui.ButtonSet.OK_CANCEL);
  if (respA.getSelectedButton() !== ui.Button.OK) return;
  const sumAAddr = respA.getResponseText().trim();
  if (!sumAAddr) return;

  const respB = ui.prompt('Option B helper', 'Enter the cell for the Option B Prob Sum (e.g., E6):', ui.ButtonSet.OK_CANCEL);
  if (respB.getSelectedButton() !== ui.Button.OK) return;
  const sumBAddr = respB.getResponseText().trim();
  if (!sumBAddr) return;

  const sumA = sh.getRange(sumAAddr);
  const checkA = sumA.offset(0, 1);
  const sumB = sh.getRange(sumBAddr);
  const checkB = sumB.offset(0, 1);

  sumA.setFormula('=SUM(FILTER(C3:C10,MOD(ROW(C3:C10),2)=1))').setNote('Option A probability sum');
  checkA.setFormula(`=IF(ABS(${sumA.getA1Notation()}-1)<=0.01,"OK","Check")`);

  sumB.setFormula('=SUM(FILTER(C18:C25,MOD(ROW(C18:C25),2)=1))').setNote('Option B probability sum');
  checkB.setFormula(`=IF(ABS(${sumB.getA1Notation()}-1)<=0.01,"OK","Check")`);

  checkA.setBackground('#C6F6D5');
  checkB.setBackground('#C6F6D5');

  SpreadsheetApp.getActive().toast('Inserted helpers', `A: ${sumAAddr}/${checkA.getA1Notation()} • B: ${sumBAddr}/${checkB.getA1Notation()}`, 4);
}

