// Lightweight validator for a single section (mirrors validateEVSheet logic)
function validateSectionPartial(sh, name, start, end) {
  const tol = 0.01;
  const col = 3; // C
  const nRows = end - start + 1;

  // Clear previous highlights/notes for the section
  const secRange = sh.getRange(start, col, nRows, 1);
  secRange.clearNote();
  secRange.setBackground(null);

  const vals = secRange.getValues().map(v => v[0]);

  let probCells = [];
  let payoffCells = [];
  for (let i = 0; i < nRows; i++) {
    const rowNum = start + i;
    if (rowNum % 2 === 1) {
      probCells.push({ i, rowNum, val: vals[i] });
    } else {
      payoffCells.push({ i, rowNum, val: vals[i] });
    }
  }

  // Safer pairing logic with orphan payoff flag
  const pairs = [];
  const len = Math.min(probCells.length, payoffCells.length);
  for (let k = 0; k < len; k++) {
    pairs.push({ p: probCells[k], x: payoffCells[k] });
  }
  if (payoffCells.length > probCells.length) {
    for (let k = len; k < payoffCells.length; k++) {
      const xr = sh.getRange(payoffCells[k].rowNum, col);
      xr.setBackground('#FFD7AE').setNote('Payoff has no matching probability above.');
    }
  }

  let probSum = 0;
  pairs.forEach(({ p, x }) => {
    const pRange = sh.getRange(p.rowNum, col);
    const xRange = sh.getRange(x.rowNum, col);

    const pBlank = p.val === '' || p.val === null;
    const xBlank = x.val === '' || x.val === null;

    // Incomplete pair
    if ((pBlank && !xBlank) || (!pBlank && xBlank)) {
      [pRange, xRange].forEach(rr => rr.setBackground('#FFD7AE')); // orange
    }

    // Probability checks
    if (!pBlank) {
      if (typeof p.val !== 'number' || isNaN(p.val)) {
        pRange.setBackground('#F8A8A8').setNote('Probability must be a number in [0,1].');
      } else if (p.val < 0 || p.val > 1) {
        pRange.setBackground('#F8A8A8').setNote('Probability must be between 0 and 1.');
      } else {
        probSum += p.val;
      }
    }

    // Payoff checks
    if (!xBlank) {
      if (typeof x.val !== 'number' || isNaN(x.val)) {
        xRange.setBackground('#F8A8A8').setNote('Payoff must be numeric.');
      }
    }
  });

  // Probability sum check (if any probs entered)
  if (probSum > 0 && Math.abs(probSum - 1) > 0.01) {
    probCells.forEach(p => {
      sh.getRange(p.rowNum, col).setBackground('#FFF3B0'); // yellow
    });
  }
}

Want me to add a compact sidebar that summarizes EV, worst case, variance for each option in real time?

Yes—here’s a compact, auto-refreshing sidebar. It computes EV, Worst Case, and Variance for Options A and B (using the same pairing logic) and refreshes every ~1.5s while open. It also shows probability sums and basic health flags.

