function openEVSidebar() {
  const html = HtmlService.createHtmlOutputFromFile('Sidebar')
    .setTitle('EV Summary');
  SpreadsheetApp.getUi().showSidebar(html);
}

function getEVSummary() {
  const sh = SpreadsheetApp.getActiveSheet();
  const col = 3; // C
  const sections = [
    { key: 'A', name: 'Option A', start: 3, end: 10, evCell: 'C12', wcCell: 'C13', varCell: 'C14' },
    { key: 'B', name: 'Option B', start: 18, end: 25, evCell: 'C27', wcCell: 'C28', varCell: 'C29' },
  ];

  const out = {};
  sections.forEach(sec => {
    const nRows = sec.end - sec.start + 1;
    const vals = sh.getRange(sec.start, col, nRows, 1).getValues().map(r => r[0]);

    const probs = [];
    const pays = [];
    for (let i = 0; i < nRows; i++) {
      const globalRow = sec.start + i;
      if (globalRow % 2 === 1) probs.push(vals[i]); else pays.push(vals[i]);
    }

    // Pair and compute
    const len = Math.min(probs.length, pays.length);
    let probSum = 0, ev = 0;
    for (let k = 0; k < len; k++) {
      const p = Number(probs[k]);
      const x = Number(pays[k]);
      if (!isNaN(p) && !isNaN(x)) {
        ev += p * x;
        if (p >= 0 && p <= 1) probSum += p;
      }
    }

    // Worst case from payoffs (numeric only)
    const numericPays = pays.map(Number).filter(v => !isNaN(v));
    const worst = numericPays.length ? Math.min.apply(null, numericPays) : null;

    // Variance (prob-weighted)
    let variance = null;
    if (len > 0 && isFinite(ev)) {
      let varSum = 0;
      for (let k = 0; k < len; k++) {
        const p = Number(probs[k]);
        const x = Number(pays[k]);
        if (!isNaN(p) && !isNaN(x)) varSum += p * Math.pow(x - ev, 2);
      }
      variance = varSum;
    }

    // Also read the sheet’s EV/WC/Var cells if present (safer display)
    const evCellVal = safeGet_(sh, sec.evCell);
    const wcCellVal = safeGet_(sh, sec.wcCell);
    const varCellVal = safeGet_(sh, sec.varCell);

    out[sec.key] = {
      name: sec.name,
      probSum: round3_(probSum),
      probOk: Math.abs(probSum - 1) <= 0.01,
      evCalc: isFinite(ev) ? round2_(ev) : null,
      evCell: toNumberOrNull_(evCellVal),
      worstCalc: worst !== null ? round2_(worst) : null,
      worstCell: toNumberOrNull_(wcCellVal),
      varCalc: variance !== null ? round2_(variance) : null,
      varCell: toNumberOrNull_(varCellVal),
      stdCalc: variance !== null ? round2_(Math.sqrt(variance)) : null
    };
  });

  return out;
}

// Helpers
function safeGet_(sh, a1) {
  try { return sh.getRange(a1).getValue(); } catch (_) { return null; }
}
function toNumberOrNull_(v) {
  const n = Number(v);
  return isNaN(n) ? null : n;
}
function round2_(x) {
  return Math.round(x * 100) / 100;
}
function round3_(x) {
  return Math.round(x * 1000) / 1000;
}

Sidebar.html (create a new file: File > New > Html, name it Sidebar)
<!DOCTYPE html>
<html>
<head>
  <base target="_top">
  <style>
    body { font: 13px Arial, sans-serif; padding: 10px; }
    .row { display: flex; justify-content: space-between; margin: 4px 0; }
    .hdr { font-weight: bold; margin-top: 8px; }
    .pill { padding: 2px 6px; border-radius: 10px; font-size: 11px; }
    .ok { background:#C6F6D5; }
    .warn { background:#FFF3B0; }
    .bad { background:#F8A8A8; }
    .small { color:#555; font-size:11px; }
    button { margin-right: 6px; }
  </style>
</head>
<body>
  <div class="hdr">EV Summary</div>
  <div id="content">Loading…</div>
  <div style="margin-top:10px;">
    <button onclick="refresh()">Refresh</button>
    <button id="autoBtn" onclick="toggleAuto()">Auto: On</button>
    <span class="small">Updates ~1.5s</span>
  </div>

  <script>
    let auto = true, timer = null;

    function cls(v) {
      if (v === true) return 'pill ok';
      if (v === false) return 'pill bad';
      return 'pill warn';
    }

    function fmt(x) {
      return (x === null || x === undefined || Number.isNaN(x)) ? '—' : x.toLocaleString();
    }

    function render(data) {
      const blocks = ['A','B'].map(k => {
        const d = data[k];
        const probClass = d.probOk ? 'ok' : 'warn';
        return `
          <div class="hdr">${d.name}</div>
          <div class="row"><div>Prob sum</div><div><span class="pill ${probClass}">${fmt(d.probSum)} ${d.probOk ? 'OK' : 'Check'}</span></div></div>
          <div class="row"><div>EV</div><div>${fmt(d.evCell ?? d.evCalc)}</div></div>
          <div class="row"><div>Worst case</div><div>${fmt(d.worstCell ?? d.worstCalc)}</div></div>
          <div class="row"><div>Variance</div><div>${fmt(d.varCell ?? d.varCalc)}</div></div>
          <div class="row"><div>Std dev</div><div>${fmt(d.stdCalc)}</div></div>
        `;
      }).join('');
      document.getElementById('content').innerHTML = blocks;
    }

    function refresh() {
      google.script.run.withSuccessHandler(render).getEVSummary();
    }

    function startAuto() {
      if (timer) clearInterval(timer);
      timer = setInterval(refresh, 1500);
    }

    function toggleAuto() {
      auto = !auto;
      document.getElementById('autoBtn').textContent = 'Auto: ' + (auto ? 'On' : 'Off');
      if (auto) startAuto(); else if (timer) clearInterval(timer);
    }

    // Initial load
    refresh();
    startAuto();
  </script>
</body>
</html>

