function insertProbSumHelpers() {
  const ui = SpreadsheetApp.getUi();
  const sh = SpreadsheetApp.getActiveSheet();

  const respA = ui.prompt('Option A helper', 'Enter the cell for the Option A Prob Sum (e.g., E3):', ui.ButtonSet.OK_CANCEL);
  if (respA.getSelectedButton() !== ui.Button.OK) return;
  const sumAAddr = respA.getResponseText().trim();
  if (!sumAAddr) return;

  const respB = ui.prompt('Option B helper', 'Enter the cell for the Option B Prob Sum (e.g., E6):', ui.ButtonSet.OK_CANCEL);
  if (respB.getSelectedButton() !== ui.Button.OK) return;
