      name: sec.name,
      probSum: round3_(probSum),
      probOk: Math.abs(probSum - 1) <= 0.01,
      evCalc: isFinite(ev) ? round2_(ev) : null,
      evCell: toNumberOrNull_(evCellVal),
      worstCalc: worst !== null ? round2_(worst) : null,
      worstCell: toNumberOrNull_(wcCellVal),
      varCalc: variance !== null ? round2_(variance) : null,
      varCell: toNumberOrNull_(varCellVal),
      stdCalc: variance !== null ? round2_(Math.sqrt(variance)) : null
    };
  });

  return out;
}

// Helpers for sidebar/summary
function safeGet_(sh, a1) {
  try { return sh.getRange(a1).getValue(); } catch (_) { return null; }
}
function toNumberOrNull_(v) {
  const n = Number(v);
  return isNaN(n) ? null : n;
}
function round2_(x) {
  return Math.round(x * 100) / 100;
}
function round3_(x) {
  return Math.round(x * 1000) / 1000;
}

// Copy summary to dedicated sheet (with formatting)
function writeEVSummaryToSheet() {
  const ss = SpreadsheetApp.getActive();
  const shData = SpreadsheetApp.getActiveSheet();
  const outSheetName = 'EV Summary';
  const col = 3; // C
  const sections = [
    { key: 'A', name: 'Option A', start: 3, end: 10 },
    { key: 'B', name: 'Option B', start: 18, end: 25 },
  ];

  const compute = (sec) => {
    const nRows = sec.end - sec.start + 1;
    const vals = shData.getRange(sec.start, col, nRows, 1).getValues().map(r => r[0]);

    const probs = [], pays = [];
    for (let i = 0; i < nRows; i++) {
      const globalRow = sec.start + i;
      if (globalRow % 2 === 1) probs.push(vals[i]); else pays.push(vals[i]);
    }

    const len = Math.min(probs.length, pays.length);
    let probSum = 0, ev = 0;
    for (let k = 0; k < len; k++) {
      const p = Number(probs[k]);
      const x = Number(pays[k]);
      if (!isNaN(p) && !isNaN(x)) {
        ev += p * x;
        if (p >= 0 && p <= 1) probSum += p;
      }
    }
    const numericPays = pays.map(Number).filter(v => !isNaN(v));
    const worst = numericPays.length ? Math.min.apply(null, numericPays) : null;

    let variance = null;
    if (len > 0 && isFinite(ev)) {
      let varSum = 0;
      for (let k = 0; k < len; k++) {
        const p = Number(probs[k]);
        const x = Number(pays[k]);
        if (!isNaN(p) && !isNaN(x)) varSum += p * Math.pow(x - ev, 2);
      }
      variance = varSum;
    }

    return {
      option: sec.name,
      probSum: isFinite(probSum) ? probSum : null,
      probOk: Math.abs(probSum - 1) <= 0.01,
      ev: isFinite(ev) ? ev : null,
      worst: worst !== null ? worst : null,
      variance: variance !== null ? variance : null,
      std: (variance !== null) ? Math.sqrt(variance) : null
    };
  };

  const now = new Date();
  const results = sections.map(compute);

  let out = ss.getSheetByName(outSheetName);
  if (!out) out = ss.insertSheet(outSheetName);

  const header = ['Timestamp', 'Option', 'Prob Sum', 'Prob OK', 'EV', 'Worst Case', 'Variance', 'Std Dev'];
  if (out.getLastRow() === 0) {
    out.getRange(1, 1, 1, header.length).setValues([header]);
  }

  const rows = results.map(r => [
    now,
    r.option,
    r.probSum,
    r.probOk ? 'OK' : 'Check',
    r.ev,
    r.worst,
    r.variance,
    r.std
  ]);

  out.getRange(out.getLastRow() + 1, 1, rows.length, header.length).setValues(rows);

  // Formatting niceties (optional)
  out.setFrozenRows(1);
  const lastRow = out.getLastRow();
  const lastCol = out.getLastColumn();
  out.getRange(1, 1, 1, lastCol).setFontWeight('bold');
  out.autoResizeColumns(1, lastCol);

  // Timestamp and numeric formats
  out.getRange(2, 1, Math.max(0, lastRow - 1), 1).setNumberFormat('yyyy-mm-dd hh:mm:ss');
  if (lastRow > 1 && lastCol >= 8) {
    out.getRange(2, 3, lastRow - 1, 1).setNumberFormat('0.000'); // Prob Sum
    out.getRange(2, 5, lastRow - 1, 4).setNumberFormat('0.00');  // EV, Worst, Var, Std
  }

  return true;
}

