// Debounced onEdit: validates only the edited section
function onEdit(e) {
  try {
    const sh = e.range.getSheet();
    const col = e.range.getColumn();
    const row = e.range.getRow();
    if (col !== 3) return; // only watch column C

    if (row >= 3 && row <= 10) {
      debounceAndValidateSection_(sh, 'Option A', 3, 10, 'A');
    } else if (row >= 18 && row <= 25) {
      debounceAndValidateSection_(sh, 'Option B', 18, 25, 'B');
    }
  } catch (_) {
    // swallow errors in simple trigger
  }
}

// Debounce per section (~300 ms); coalesces rapid edits/pastes
function debounceAndValidateSection_(sh, name, start, end, keySuffix) {
  const cache = CacheService.getDocumentCache();
  const key = 'ev_debounce_' + keySuffix;
  const hit = cache.get(key);
  if (hit) return;

  cache.put(key, '1', 1); // seconds
  Utilities.sleep(300);
  validateSectionPartial(sh, name, start, end);
  SpreadsheetApp.getActive().toast(name + ' validated', 'EV Tools', 3);
}

// Lightweight validator for a single section
function validateSectionPartial(sh, name, start, end) {
  const tol = 0.01;
  const col = 3; // C
  const nRows = end - start + 1;

  const secRange = sh.getRange(start, col, nRows, 1);
  secRange.clearNote();
  secRange.setBackground(null);

  const vals = secRange.getValues().map(v => v[0]);

  let probCells = [];
  let payoffCells = [];
  for (let i = 0; i < nRows; i++) {
    const rowNum = start + i;
    if (rowNum % 2 === 1) {
      probCells.push({ i, rowNum, val: vals[i] });
    } else {
      payoffCells.push({ i, rowNum, val: vals[i] });
    }
  }

  const pairs = [];
  const len = Math.min(probCells.length, payoffCells.length);
  for (let k = 0; k < len; k++) {
    pairs.push({ p: probCells[k], x: payoffCells[k] });
  }
  if (payoffCells.length > probCells.length) {
    for (let k = len; k < payoffCells.length; k++) {
      const xr = sh.getRange(payoffCells[k].rowNum, col);
      xr.setBackground('#FFD7AE').setNote('Payoff has no matching probability above.');
    }
  }

  let probSum = 0;
  pairs.forEach(({ p, x }) => {
    const pRange = sh.getRange(p.rowNum, col);
    const xRange = sh.getRange(x.rowNum, col);

    const pBlank = p.val === '' || p.val === null;
    const xBlank = x.val === '' || x.val === null;

    if ((pBlank && !xBlank) || (!pBlank && xBlank)) {
      [pRange, xRange].forEach(rr => rr.setBackground('#FFD7AE')); // orange
    }

    if (!pBlank) {
      if (typeof p.val !== 'number' || isNaN(p.val)) {
        pRange.setBackground('#F8A8A8').setNote('Probability must be a number in [0,1].');
      } else if (p.val < 0 || p.val > 1) {
        pRange.setBackground('#F8A8A8').setNote('Probability must be between 0 and 1.');
      } else {
        probSum += p.val;
      }
    }

    if (!xBlank) {
      if (typeof x.val !== 'number' || isNaN(x.val)) {
        xRange.setBackground('#F8A8A8').setNote('Payoff must be numeric.');
      }
    }
  });

  if (probSum > 0 && Math.abs(probSum - 1) > 0.01) {
    probCells.forEach(p => {
      sh.getRange(p.rowNum, col).setBackground('#FFF3B0'); // yellow
    });
  }
}

// Sidebar: open and compute summary
function openEVSidebar() {
  const html = HtmlService.createHtmlOutputFromFile('Sidebar').setTitle('EV Summary');
  SpreadsheetApp.getUi().showSidebar(html);
}

function getEVSummary() {
  const sh = SpreadsheetApp.getActiveSheet();
  const col = 3; // C
  const sections = [
    { key: 'A', name: 'Option A', start: 3, end: 10, evCell: 'C12', wcCell: 'C13', varCell: 'C14' },
    { key: 'B', name: 'Option B', start: 18, end: 25, evCell: 'C27', wcCell: 'C28', varCell: 'C29' },
  ];

  const out = {};
  sections.forEach(sec => {
    const nRows = sec.end - sec.start + 1;
    const vals = sh.getRange(sec.start, col, nRows, 1).getValues().map(r => r[0]);

    const probs = [];
    const pays = [];
    for (let i = 0; i < nRows; i++) {
      const globalRow = sec.start + i;
      if (globalRow % 2 === 1) probs.push(vals[i]); else pays.push(vals[i]);
    }

    const len = Math.min(probs.length, pays.length);
    let probSum = 0, ev = 0;
    for (let k = 0; k < len; k++) {
      const p = Number(probs[k]);
      const x = Number(pays[k]);
      if (!isNaN(p) && !isNaN(x)) {
        ev += p * x;
        if (p >= 0 && p <= 1) probSum += p;
      }
    }

    const numericPays = pays.map(Number).filter(v => !isNaN(v));
    const worst = numericPays.length ? Math.min.apply(null, numericPays) : null;

    let variance = null;
    if (len > 0 && isFinite(ev)) {
      let varSum = 0;
      for (let k = 0; k < len; k++) {
        const p = Number(probs[k]);
        const x = Number(pays[k]);
        if (!isNaN(p) && !isNaN(x)) varSum += p * Math.pow(x - ev, 2);
      }
      variance = varSum;
    }

    const evCellVal = safeGet_(sh, sec.evCell);
    const wcCellVal = safeGet_(sh, sec.wcCell);
    const varCellVal = safeGet_(sh, sec.varCell);

    out[sec.key] = {
      name: sec.name,
      probSum: round3_(probSum),
      probOk: Math.abs(probSum - 1) <= 0.01,
      evCalc: isFinite(ev) ? round2_(ev) : null,
      evCell: toNumberOrNull_(evCellVal),
      worstCalc: worst !== null ? round2_(worst) : null,
      worstCell: toNumberOrNull_(wcCellVal),
      varCalc: variance !== null ? round2_(variance) : null,
      varCell: toNumberOrNull_(varCellVal),
      stdCalc: variance !== null ? round2_(Math.sqrt(variance)) : null
    };
  });

  return out;
}

// Helpers for sidebar/summary
function safeGet_(sh, a1) {
  try { return sh.getRange(a1).getValue(); } catch (_) { return null; }
}
function toNumberOrNull_(v) {
  const n = Number(v);
  return isNaN(n) ? null : n;
}
function round2_(x) {
  return Math.round(x * 100) / 100;
}
function round3_(x) {
  return Math.round(x * 1000) / 1000;
}

// Copy summary to dedicated sheet (with formatting)
function writeEVSummaryToSheet() {
  const ss = SpreadsheetApp.getActive();
  const shData = SpreadsheetApp.getActiveSheet();
  const outSheetName = 'EV Summary';
  const col = 3; // C
  const sections = [
    { key: 'A', name: 'Option A', start: 3, end: 10 },
    { key: 'B', name: 'Option B', start: 18, end: 25 },
  ];

  const compute = (sec) => {
    const nRows = sec.end - sec.start + 1;
    const vals = shData.getRange(sec.start, col, nRows, 1).getValues().map(r => r[0]);

    const probs = [], pays = [];
    for (let i = 0; i < nRows; i++) {
      const globalRow = sec.start + i;
      if (globalRow % 2 === 1) probs.push(vals[i]); else pays.push(vals[i]);
    }

    const len = Math.min(probs.length, pays.length);
    let probSum = 0, ev = 0;
    for (let k = 0; k < len; k++) {
      const p = Number(probs[k]);
      const x = Number(pays[k]);
      if (!isNaN(p) && !isNaN(x)) {
        ev += p * x;
        if (p >= 0 && p <= 1) probSum += p;
      }
    }
    const numericPays = pays.map(Number).filter(v => !isNaN(v));
    const worst = numericPays.length ? Math.min.apply(null, numericPays) : null;

    let variance = null;
    if (len > 0 && isFinite(ev)) {
      let varSum = 0;
      for (let k = 0; k < len; k++) {
        const p = Number(probs[k]);
        const x = Number(pays[k]);
        if (!isNaN(p) && !isNaN(x)) varSum += p * Math.pow(x - ev, 2);
      }
      variance = varSum;
    }

    return {
      option: sec.name,
      probSum: isFinite(probSum) ? probSum : null,
      probOk: Math.abs(probSum - 1) <= 0.01,
      ev: isFinite(ev) ? ev : null,
      worst: worst !== null ? worst : null,
      variance: variance !== null ? variance : null,
      std: (variance !== null) ? Math.sqrt(variance) : null
    };
  };

  const now = new Date();
  const results = sections.map(compute);

  let out = ss.getSheetByName(outSheetName);
  if (!out) out = ss.insertSheet(outSheetName);

  const header = ['Timestamp', 'Option', 'Prob Sum', 'Prob OK', 'EV', 'Worst Case', 'Variance', 'Std Dev'];
  if (out.getLastRow() === 0) {
    out.getRange(1, 1, 1, header.length).setValues([header]);
  }

  const rows = results.map(r => [
    now,
    r.option,
    r.probSum,
    r.probOk ? 'OK' : 'Check',
    r.ev,
    r.worst,
    r.variance,
    r.std
  ]);

  out.getRange(out.getLastRow() + 1, 1, rows.length, header.length).setValues(rows);

  // Formatting niceties (optional)
  out.setFrozenRows(1);
  const lastRow = out.getLastRow();
  const lastCol = out.getLastColumn();
  out.getRange(1, 1, 1, lastCol).setFontWeight('bold');
  out.autoResizeColumns(1, lastCol);

  // Timestamp and numeric formats
  out.getRange(2, 1, Math.max(0, lastRow - 1), 1).setNumberFormat('yyyy-mm-dd hh:mm:ss');
  if (lastRow > 1 && lastCol >= 8) {
    out.getRange(2, 3, lastRow - 1, 1).setNumberFormat('0.000'); // Prob Sum
    out.getRange(2, 5, lastRow - 1, 4).setNumberFormat('0.00');  // EV, Worst, Var, Std
  }

  return true;
}

